let answerJob=null,previewTimer=null,testId=null,buildingTest=false,testProgress='',testError='',dismissedUpdate=null,updateState={status:'idle',currentVersion:'0.1.10'},localAIState={installed:false,status:'not-installed',progress:0,message:''},S,connected=false,connectionPersistent=true,chatGPTState={connected:false,enabled:false,accounts:[]},signingIn=false,availableModels=[],connectionFeedback='',testedModel='',testingConnection=false,view='home',subjectId=null,sourceFolder='all',tab='Tutor',chatId=null,lessonId=null,noteId=null,example='',busy=false,error='',draft='',activeSources=[],contextSource=null,contextPage=1,saveTimer,toastTimer,importing=false,board=null;
