document.addEventListener('click',e=>{const w=e.target.closest('[data-window]');if(w)api.window(w.dataset.window);const link=e.target.closest('.message-text a');if(link){e.preventDefault();toast('Copy the link to open it in your browser.')}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#modal').open)searchDialog()}});
const handle=$('#resize-handle');handle.onpointerdown=e=>{handle.setPointerCapture(e.pointerId);const start=e.clientX,width=S.settings.sidebarWidth;const move=event=>{S.settings.sidebarWidth=Math.max(190,Math.min(360,width+event.clientX-start));applyTheme()};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);persist()};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end)};handle.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){S.settings.sidebarWidth=Math.max(190,Math.min(360,S.settings.sidebarWidth+(e.key==='ArrowLeft'?-8:8)));applyTheme();persist()}};
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
api.onLocalAIStatus(info=>{localAIState=info;if(view==='settings'&&S.settings.aiMode==='local'){const panel=$('#local-ai-panel');if(panel){panel.outerHTML=localAISettings();if($('#local-thinking'))$('#local-thinking').onchange=e=>{S.settings.localThinking=e.target.checked;persist()};icons()}}});
function renderStreamingAnswer(){if(!responseHere())return;const thinking=$('.thinking');if(!thinking)return;$('#thinking-label').textContent=answerJob.status;let preview=$('#local-answer-preview');if(!answerJob.text){preview?.remove();return}if(!preview){preview=document.createElement('div');preview.id='local-answer-preview';preview.className='message-text streaming-answer';preview.dir='auto';if(subject()?.name==='Arabic')preview.lang='ar';thinking.after(preview)}const scroll=$('.chat-scroll'),follow=scroll&&scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<100;preview.innerHTML=md(answerJob.text);mathRender(preview);if(follow)scroll.scrollTop=scroll.scrollHeight;}
api.onProgress(info=>{if(buildingTest){if(['test','status'].includes(info.type)){testProgress=info.text;if($('#test-progress'))$('#test-progress').textContent=info.text}return}if(info.type==='import'){toast(info.text);return}if(!answerJob||info.requestId!==answerJob.requestId||info.chatId!==answerJob.chatId||info.subjectId!==answerJob.subjectId)return;if(info.type==='answer'){answerJob.text=info.text;if(!previewTimer)previewTimer=setTimeout(()=>{previewTimer=null;renderStreamingAnswer()},90)}else if(info.type==='status'){answerJob.status=info.text;answerJob.text='';renderStreamingAnswer()}});
async function init(){S=StudoraTests.normalize(StudoraSources.normalize(await api.load()));S.subjects.forEach(s=>s.lessonStructure=StudoraLessons.structure(s));updateState=await api.updateStatus();chatGPTState=await api.chatGPTStatus();localAIState=await api.localAIStatus();if(S.settings.aiMode==='local'){S.settings.model='studora-local-gemma4-e4b'}const connection=await api.keyStatus();connected=connection.connected;connectionPersistent=connection.persistent;if(localAIState.installed&&(S.settings.aiMode||'chatgpt')==='chatgpt'&&!(chatGPTState.connected&&chatGPTState.enabled)){S.settings.aiMode='local';S.settings.model='studora-local-gemma4-e4b'}subjectId=S.ui.subject;chatId=S.ui.chat;lessonId=S.ui.lesson;testId=S.ui.test||null;tab=S.ui.tab||'Tutor';view=S.ui.view||'home';if(subjectId&&!subject())view='home';if(view==='subject')activeSources=chat()?.sourceIds||(lesson()?lessonSourceIds(lesson()):null)||subjectsSources().map(x=>x.id);draft=chat()?.draft||'';render()}
init().catch(e=>{$('#main').innerHTML='<div class="content"><h1>Could not open your workspace</h1><p>'+esc(e.message)+'</p></div>'});
